class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # month -> {name: size}
        self._files: dict[str, dict[str, int]] = {}
        # month -> set of names already counted in that month
        self._counted: dict[str, set[str]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0")

        files = self._files.setdefault(month, {})
        counted = self._counted.setdefault(month, set())

        # Re-uploading same name in same month: no additional quota counted
        if name in counted:
            files[name] = size_bytes
            return

        # Check limit
        if self.used_bytes(month) + size_bytes > self._limit_bytes:
            raise ValueError("Upload would exceed monthly limit")

        files[name] = size_bytes
        counted.add(name)

    def delete(self, name: str, month: str) -> None:
        files = self._files.get(month)
        if files is not None and name in files:
            del files[name]
        # Quota is not returned in the current month;
        # the name remains in _counted so its size still counts.

    def used_bytes(self, month: str) -> int:
        files = self._files.get(month, {})
        counted = self._counted.get(month, set())
        return sum(size for name, size in files.items() if name in counted)
